/**
 * Action Provenance Verification (§6.16 AP1–AP2).
 *
 * Verifies that any claimed state-altering external action (social posts, git commits/PRs, LinkedIn updates)
 * generated by an agent is backed by an attested egress receipt or released held request in the run's audit trail.
 * Unverified action assertions are replaced with a standardized safety banner, and flagged on the ledger.
 */

export type ActionClaimKind = 'x_post' | 'github_commit' | 'github_pr' | 'linkedin_post';

export type ActionClaim = {
  kind: ActionClaimKind;
  evidence: string;
  matchedText: string;
};

export const SAFETY_BANNER =
  '⚠️ Action unverified: Agent claimed to complete an action, but no upstream receipt was found in the audit trail. Nothing was executed.';

/**
 * Scans text content for external resource URLs or explicit execution assertions.
 */
export function detectActionClaims(text: string): ActionClaim[] {
  if (!text || typeof text !== 'string') return [];
  const claims: ActionClaim[] = [];

  // 1. X / Twitter status claim: e.g. https://x.com/user/status/12345 or https://twitter.com/user/status/12345
  const xRegex = /https?:\/\/(?:www\.)?(?:twitter\.com|x\.com)\/(?:[a-zA-Z0-9_]{1,15}\/status\/(\d+)|i\/web\/status\/(\d+))/g;
  for (const match of text.matchAll(xRegex)) {
    claims.push({
      kind: 'x_post',
      evidence: match[1] || match[2],
      matchedText: match[0],
    });
  }

  // Also check explicit "Posted to X: ..." or "Tweeted: ..." with URL
  const xExplicitRegex = /(?:posted to x|tweeted|published to x)[^\n]*?(https?:\/\/(?:twitter\.com|x\.com)\/\S+)/gi;
  for (const match of text.matchAll(xExplicitRegex)) {
    if (!claims.some((c) => c.matchedText === match[1])) {
      claims.push({
        kind: 'x_post',
        evidence: match[1],
        matchedText: match[1],
      });
    }
  }

  // 2. GitHub commit or PR claim
  const ghCommitRegex = /https?:\/\/github\.com\/([^\/\s]+\/[^\/\s]+)\/commit\/([0-9a-f]{7,40})/g;
  for (const match of text.matchAll(ghCommitRegex)) {
    claims.push({
      kind: 'github_commit',
      evidence: `${match[1]}@${match[2]}`,
      matchedText: match[0],
    });
  }

  const ghPrRegex = /https?:\/\/github\.com\/([^\/\s]+\/[^\/\s]+)\/pull\/(\d+)/g;
  for (const match of text.matchAll(ghPrRegex)) {
    claims.push({
      kind: 'github_pr',
      evidence: `${match[1]}#${match[2]}`,
      matchedText: match[0],
    });
  }

  // 3. LinkedIn post claim
  const liRegex = /https?:\/\/(?:www\.)?linkedin\.com\/feed\/update\/urn:li:(?:share|activity):(\d+)/g;
  for (const match of text.matchAll(liRegex)) {
    claims.push({
      kind: 'linkedin_post',
      evidence: match[1],
      matchedText: match[0],
    });
  }

  return claims;
}

/**
 * Checks whether the immutable ledger entries for this run contain an attested egress or released hold receipt
 * confirming the claimed action took place.
 */
export function hasAttestedReceipt(claim: ActionClaim, runRows: Array<Record<string, unknown>>): boolean {
  for (const row of runRows) {
    const route = typeof row.route === 'string' ? row.route.toLowerCase() : '';
    const host = typeof row.host === 'string' ? row.host.toLowerCase() : '';
    const action = typeof row.action === 'string' ? row.action : '';
    const isEgress = action === 'EGRESS' || action === 'HELD_REQUEST_RELEASED';

    if (claim.kind === 'x_post') {
      if ((route === 'x' || route === 'twitter' || host.includes('x.com') || host.includes('twitter.com')) && isEgress) {
        return true;
      }
    } else if (claim.kind === 'github_commit' || claim.kind === 'github_pr') {
      if ((route === 'github' || host.includes('github.com')) && isEgress) {
        return true;
      }
    } else if (claim.kind === 'linkedin_post') {
      if ((route === 'linkedin' || host.includes('linkedin.com')) && isEgress) {
        return true;
      }
    }
  }
  return false;
}

export type ProvenanceVerificationResult = {
  verified: boolean;
  sanitizedText: string;
  unverifiedClaims: ActionClaim[];
};

/**
 * Validates text against run audit rows. If unverified claims are detected, replaces them with SAFETY_BANNER.
 */
export function verifyActionProvenance(
  text: string,
  runRows: Array<Record<string, unknown>>,
): ProvenanceVerificationResult {
  const claims = detectActionClaims(text);
  if (claims.length === 0) {
    return { verified: true, sanitizedText: text, unverifiedClaims: [] };
  }

  const unverifiedClaims: ActionClaim[] = [];
  for (const claim of claims) {
    if (!hasAttestedReceipt(claim, runRows)) {
      unverifiedClaims.push(claim);
    }
  }

  if (unverifiedClaims.length === 0) {
    return { verified: true, sanitizedText: text, unverifiedClaims: [] };
  }

  let sanitizedText = text;
  for (const unverified of unverifiedClaims) {
    const escaped = unverified.matchedText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const lineRegex = new RegExp(`^.*${escaped}.*$`, 'm');
    if (lineRegex.test(sanitizedText)) {
      sanitizedText = sanitizedText.replace(lineRegex, SAFETY_BANNER);
    } else {
      sanitizedText = sanitizedText.replace(unverified.matchedText, `[UNVERIFIED: ${unverified.kind}]`) + `\n\n${SAFETY_BANNER}`;
    }
  }

  return {
    verified: false,
    sanitizedText,
    unverifiedClaims,
  };
}

/**
 * Deeply sanitizes output objects or strings, verifying action provenance against run ledger rows.
 */
export function sanitizeOutputWithProvenance(
  output: unknown,
  runRows: Array<Record<string, unknown>>,
): { sanitized: unknown; unverifiedClaims: ActionClaim[] } {
  const allClaims: ActionClaim[] = [];

  function walk(val: unknown): unknown {
    if (typeof val === 'string') {
      const res = verifyActionProvenance(val, runRows);
      if (!res.verified) {
        allClaims.push(...res.unverifiedClaims);
        return res.sanitizedText;
      }
      return val;
    }
    if (Array.isArray(val)) {
      return val.map(walk);
    }
    if (val && typeof val === 'object') {
      const copy: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(val as Record<string, unknown>)) {
        copy[k] = walk(v);
      }
      return copy;
    }
    return val;
  }

  const sanitized = walk(output);
  return { sanitized, unverifiedClaims: allClaims };
}
